import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        String s = r.next().toLowerCase();
        r.next();
        List<String> words = new ArrayList<>();
        for (String w = r.next(); !w.isEmpty(); w = r.next()) words.add(w);
        int left = 0, answer = 0;
        for (int right = 0; right < s.length(); right++) {
            for (String word : words) {
                int start = right - word.length() + 1;
                if (start >= 0 && s.startsWith(word, start)) left = Math.max(left, start + 1);
            }
            answer = Math.max(answer, right - left + 1);
        }
        System.out.println(answer);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	s := strings.ToLower(readToken())
	readToken()
	var words []string
	for w := readToken(); w != ""; w = readToken() {
		words = append(words, w)
	}
	left, answer := 0, 0
	for right := range s {
		for _, word := range words {
			start := right - len(word) + 1
			if start >= 0 && s[start:right+1] == word {
				left = max(left, start+1)
			}
		}
		answer = max(answer, right-left+1)
	}
	fmt.Println(answer)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
